use vstd::prelude::*;
use vstd::string::*;

verus! {

spec fn is_lowercase_or_comma(c: char) -> bool {
    ('a' as int <= c as int && c as int <= 'z' as int) || c == ','
}

spec fn output_char(input: char) -> char {
    if input == ',' {
        ' '
    } else {
        input
    }
}

fn solve(s: Vec<char>) -> (result: Vec<char>)
    requires
        s@.len() == 19,
        forall |i: int| 0 <= i < s@.len() ==> is_lowercase_or_comma(s@[i]),
        s@[5] == ',',
        s@[13] == ',',
    ensures
        result@.len() == 20,
        result@[19] == '\n',
        forall |i: int| 0 <= i < 19 ==> result@[i] == output_char(s@[i]),
{
    let mut result_vec = Vec::new();
    let mut i: usize = 0;
    
    while i < s.len()
        invariant
            0 <= i <= s@.len(),
            result_vec@.len() == i,
            forall |j: int| 0 <= j < i ==> result_vec@[j] == output_char(s@[j]),
    {
        let c = s[i];
        let output_c = if c == ',' { ' ' } else { c };
        result_vec.push(output_c);
        i = i + 1;
    }
    
    // Add the newline character
    result_vec.push('\n');
    
    result_vec
}

}
